CREATE TABLE IF NOT EXISTS locations (id TEXT PRIMARY KEY, name TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, is_default INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_settings (provider TEXT PRIMARY KEY, encrypted_token TEXT, encrypted_refresh_token TEXT, token_expires_at TEXT, app_version TEXT, app_id TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scans (id TEXT PRIMARY KEY, location_id TEXT NOT NULL, threshold INTEGER NOT NULL, source TEXT NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT, finished_at TEXT, created_at TEXT NOT NULL, vendor_count INTEGER NOT NULL DEFAULT 0, product_count INTEGER NOT NULL DEFAULT 0, deal_count INTEGER NOT NULL DEFAULT 0, error_code TEXT, error_message TEXT);
CREATE TABLE IF NOT EXISTS deals (id TEXT PRIMARY KEY, scan_id TEXT NOT NULL, deal_key TEXT NOT NULL, product_variation_id TEXT NOT NULL, vendor_id TEXT NOT NULL, title TEXT NOT NULL, image TEXT, vendor_title TEXT NOT NULL, vendor_code TEXT, category_title TEXT, price_rials INTEGER NOT NULL, discount_rials INTEGER NOT NULL, final_price_rials INTEGER NOT NULL, discount_ratio INTEGER NOT NULL, stock INTEGER NOT NULL, UNIQUE(scan_id, deal_key));
CREATE INDEX IF NOT EXISTS scans_location_created ON scans(location_id, created_at DESC);
CREATE INDEX IF NOT EXISTS deals_scan_ratio ON deals(scan_id, discount_ratio DESC);
